import org.springframework.beans.factory.annotation.Value;
import org.springframework.context.annotation.*;
import org.springframework.core.env.MapPropertySource;

// 設定値を受け取る @Configuration(application.yml の shop.* を想定)
@Configuration
class ShopConfig {
    @Bean
    String banner(@Value("${shop.name:Java道場ストア}") String name,
                  @Value("${shop.tax-rate:0.10}") double taxRate) {
        return name + "(税率 " + Math.round(taxRate * 100) + "%)";
    }
}

// application.yml に書いたつもりの設定
// ここを変えてみよう:shop.name の行を消す / tax-rate を "0.10" にする
Map<String, Object> props = Map.of(
        "shop.name", "モカ珈琲店",
        "shop.tax-rate", "0.08");

var ctx = new AnnotationConfigApplicationContext();
ctx.getEnvironment().getPropertySources()
   .addFirst(new MapPropertySource("my-settings", props));
ctx.register(ShopConfig.class);
ctx.refresh();

System.out.println(ctx.getBean("banner", String.class));
// Environment から直接読むこともできる(無ければ第2引数)
System.out.println("server.port = " + ctx.getEnvironment()
        .getProperty("server.port", "8080(既定値)"));
ctx.close();

import org.springframework.context.annotation.*;

interface Notifier { String send(String to, String msg); }

class ConsoleNotifier implements Notifier {
    public String send(String to, String msg) {
        return "[送信しない] " + to + " 宛: " + msg;
    }
}

class SmtpNotifier implements Notifier {
    public String send(String to, String msg) {
        return "[SMTPで送信] " + to + " 宛: " + msg;
    }
}

@Configuration
class MailConfig {
    @Bean @Profile("prod")
    Notifier smtp() { return new SmtpNotifier(); }

    @Bean @Profile("!prod")      // prod 以外すべて(何も指定しないときも)
    Notifier console() { return new ConsoleNotifier(); }
}

// ここを変えてみよう:"dev" を "prod" に。{ } にする(プロファイルなし)とどうなる?
String[] active = { "dev" };

var ctx = new AnnotationConfigApplicationContext();
ctx.getEnvironment().setActiveProfiles(active);   // register より前に設定する
ctx.register(MailConfig.class);
ctx.refresh();

System.out.println("有効なプロファイル: "
        + String.join(",", ctx.getEnvironment().getActiveProfiles()));
System.out.println("登録された Notifier: "
        + String.join(",", ctx.getBeanNamesForType(Notifier.class)));
System.out.println(ctx.getBean(Notifier.class)
        .send("haru@example.com", "パスワード再設定のご案内"));
ctx.close();

